module brent_kung_adder (
    input [3:0] A,
    input [3:0] B,
    output [4:0] S
);
    wire [3:0] P; // Propagate
    wire [3:0] G; // Generate
    wire [3:0] C; // Carry

    assign P = A ^ B; // Propagate
    assign G = A & B; // Generate

    // Carry generation using Brent-Kung approach
    assign C[0] = 0; // C0 is always 0
    assign C[1] = G[0] | (P[0] & C[0]);
    assign C[2] = G[1] | (P[1] & G[0]) | (P[1] & P[0] & C[0]);
    assign C[3] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]) | (P[2] & P[1] & P[0] & C[0]);

    // Sum output
    assign S = {C[3], P[3:0]} ^ {C[3:0], 1'b0}; // Sum = P + C

endmodule

