            D <= 1'b1;
            @(posedge CLK);
            #2;

            #1;


            check_outputs(1'b0);
        end
        endtask

    task testcase005;

        integer i;
        begin
            test_num = test_num + 1;
            $display("Testcase %03d: Multi-cycle Retention", test_num);
            reset_dut();


            WE <= 1'b1;
            D <= 1'b1;
            @(posedge CLK);
            #2;


            WE <= 1'b0;
            for (i = 0; i < 5; i = i + 1) begin
                D <= ~D;
                @(posedge CLK);
            end
            #2;

            #1;


            check_outputs(1'b1);
        end
        endtask

