        if (weight) begin
            // Class 1
            classification = (feature1 + feature2 > THRESHOLD) ? 1'b1 : 1'b0;
        end else begin
            // Class 0
            classification = (feature1 + feature2 <= THRESHOLD) ? 1'b0 : 1'b1;
        end
    end
